import type { BackupCourseId } from './backup'

export interface ExportFixture {
  name: string
  course: BackupCourseId
  done: number[]
  weak: Record<string, number>
  days: string[]
  /** exportCode() of the prototype for this course and stored progress. */
  code: string
}

export interface ImportFixture {
  name: string
  code: string
  /** importCode() of the prototype: "invalid" = it threw; progress null = no progress inside. */
  prototype:
    | 'invalid'
    | {
        course: BackupCourseId
        progress: { done: number[]; weak: Record<string, number>; days: string[] } | null
      }
}

